  ('45f3bc5a-9753-4f59-9855-bde5836d03bd', 'mkh@mkh.com', 'Michael Hargrove', 'Records Clderk', 'dept-openrecords', NULL, NULL, 0, 0, 'active', '2026-07-08 09:06:38', '2026-07-08 09:06:16', NULL),
  ('adb14fa5-f83c-4524-8c7f-a4eeec761114', 'wjennings@city.gove', 'Wayne Jennings', 'Manager of Mounted Police', 'team-police', NULL, NULL, 0, 1, 'active', NULL, '2026-06-22 19:40:19', 'Records related to equine, mounted police, horse, or management of the barn or equine facility, as well as veterinary records, horse purchase contracts or information, barn schedule, farrier and shoeing'),
  ('b5f188ae-4840-45dd-bcf6-110cdfb380d4', 'tjones@cityemail.gov', 'Tom Jones', 'Coordinator', 'dept-openrecords', NULL, NULL, 0, 1, 'active', NULL, '2026-05-25 00:23:48', NULL),
  ('b9225db1-433a-4fee-afcc-25ed84a1cf71', 'tjackson@cityofautumnfalls.gov', 'Thomas Jackson', 'Records Archive Management', 'team-clerk-archives', NULL, NULL, 0, 1, 'active', NULL, '2026-07-01 00:18:55', 'Retrieval of paper, microfilm, and microfiche records from the City Records Center and Historical Vault - archived documents that predate the city''s digital systems and must be located by physical index and pulled by hand. Covers historical property deeds, plat maps and parcel files, land records, archived permits, older meeting minutes and correspondence, and other pre-digitization paper files.'),
