INSERT INTO "record_types" ("id", "category_id", "name", "code", "description", "intent", "expected_content", "typical_request_reason", "synonyms", "disambiguators", "keywords", "identifying_facets", "formats", "is_structured_data", "public_availability", "auto_release_eligible", "redaction_profile_id", "fee_estimate_low", "fee_estimate_high", "fee_estimate_note", "is_canonical", "status", "source", "confidence", "sort_order", "created_at", "updated_at", "fulfillment_method", "medium", "auto_publish", "mappable") VALUES
  ('rt-481168cf', 'cat-finance', 'Payroll registers', 'payroll-registers', NULL, 'Summary records of aggregate payroll disbursements for a pay period', 'Pay period dates, number of employees paid, total gross and net pay, preparer information', 'Budget analysis, financial audits, public expenditure oversight', '["payroll summaries","payroll reports"]', '["Aggregate payroll totals, not individual employee pay stubs or personnel files"]', '["payroll register","pay period","total gross","total net","employees paid"]', '["Aggregate totals without individual employee detail","pay period dates","total employee count"]', '["document","structured_data"]', 1, 'releasable', 1, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 95, 900, '2026-06-08 19:56:40', '2026-06-08 19:56:40', 'electronic_search', 'electronic', 0, 1),
  ('rt-597e8813', 'cat-finance', 'Vendor invoices', 'vendor-invoices', NULL, 'Invoices submitted by vendors for goods and services provided to the city', 'Invoice number and date, vendor name, line items with quantities and prices, subtotal, purchase order reference', 'Expenditure verification, audit support, procurement oversight, vendor payment tracking', '["supplier invoices","bills","payment requests"]', '["Vendor bills for payment, not purchase orders, contracts, or check registers"]', '["vendor invoice","invoice no","bill to","line item","PO reference","subtotal"]', '["Vendor name and address","itemized line items","PO cross-reference"]', '["document"]', 0, 'review_required', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 90, 900, '2026-06-08 19:56:40', '2026-06-08 19:56:40', 'electronic_search', 'electronic', 0, 1),
  ('rt-62fd3732', 'cat-hr', 'Employee pay stubs', 'employee-paystubs', NULL, 'Individual employee earnings statements showing pay, deductions, and withholdings', 'Employee name and ID, pay period, gross pay, deductions (taxes, benefits), net pay', 'Employment verification, wage disputes, personnel matters', '["earnings statements","pay slips","wage statements"]', '["Individual employee pay details, not aggregate payroll or salary schedules"]', '["employee earnings","pay stub","gross pay","net pay","deductions","employee ID"]', '["Individual employee identifier","detailed deduction breakdown","net pay calculation"]', '["document"]', 0, 'confidential', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 100, 900, '2026-06-08 19:56:40', '2026-06-08 19:56:40', 'electronic_search', 'electronic', 0, 1),
  ('rt-67173bdb', 'cat-hr', 'Direct deposit authorizations', 'direct-deposit-auth', NULL, 'Capture employee banking information for electronic payroll deposits', 'Employee authorizations containing bank routing numbers, account numbers (partial or full), and effective dates for direct deposit of paychecks', 'Payroll audits, financial account verification, fraud investigation', '["direct deposit form","banking authorization","electronic funds transfer authorization","ACH authorization"]', '["Contains banking details","Authorization document","Links employee to financial institution"]', '["direct deposit","bank routing","account number","authorization","ACH","electronic payment"]', '["Bank routing number","Account number (full or partial)","Effective date","Employee signature or authorization"]', '["document","structured_data"]', 1, 'confidential', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 95, 900, '2026-06-08 20:20:27', '2026-06-08 20:20:27', 'electronic_search', 'electronic', 0, 1),
  ('rt-72c64e66', 'cat-hr', 'Employee tax forms (W-2)', 'employee-w2-forms', NULL, 'Annual wage and tax reporting for employees as required by IRS', 'IRS Form W-2 data showing annual wages, federal and state withholdings, Social Security and Medicare wages for each employee', 'Employee personnel file requests, income verification, tax dispute resolution', '["W-2","wage and tax statement","annual tax form","IRS W-2"]', '["Annual, not per-pay-period","IRS form W-2 format","Includes all federally required tax fields"]', '["W-2","annual wages","tax year","federal withholding","Social Security","Medicare","tax statement"]', '["Tax year field","Annual wage totals","Federal, SS, and Medicare withholding amounts"]', '["document","structured_data"]', 1, 'confidential', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 95, 900, '2026-06-08 20:20:27', '2026-06-08 20:20:27', 'electronic_search', 'electronic', 0, 1),
  ('rt-7e644df4', 'cat-hr', 'Employee timesheets', 'employee-timesheets', NULL, 'Track hours worked by employees for payroll and project accounting', 'Daily or weekly records of regular and overtime hours worked by individual employees, often with project or cost center codes', 'Overtime analysis, labor cost verification, FLSA compliance review, project cost audits', '["time records","hours worked","time cards","labor hours"]', '["Daily or weekly hour entries","Distinguishes regular vs overtime hours","May include project codes"]', '["timesheet","hours","overtime","regular time","work date","project code","labor"]', '["Employee ID with date","Regular and overtime hour columns","Project or department codes"]', '["structured_data","document"]', 1, 'review_required', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 90, 900, '2026-06-08 20:20:27', '2026-06-08 20:20:27', 'electronic_search', 'electronic', 0, 1),
  ('rt-911-calls', 'cat-police', '911 Call Records', 'CAD-911', 'Computer-aided dispatch (911) call records. Caller identifying information is withheld; the incident type, location, time, and disposition are public.', NULL, NULL, NULL, '[]', '[]', '[]', '[]', '[]', 1, 'redacted', 0, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 100, '2026-07-04 03:48:54', '2026-07-04 03:48:54', 'electronic_search', 'electronic', 1, 1),
  ('rt-911-recordings', 'cat-police', '911 call recordings', '911-recordings', 'Audio of a 911 or non-emergency call as placed by the caller.', 'Capture the audio of a 911 or non-emergency call as placed by the caller.', 'The caller voice, what they reported, dispatcher questions, background audio, and call timing.', 'Requested to hear what a caller said or reported about a specific incident.', '["911 call","911 audio","911 recording","emergency call recording","call audio"]', '["not the CAD or dispatch log","not body-cam audio"]', '["911","emergency call","recording","audio","caller"]', '["call date and time","phone number","address","incident or call number"]', '["audio"]', 0, 'review_required', 0, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 60, '2026-06-05 19:04:12', '2026-06-05 19:04:12', 'manual_collection', 'electronic', 0, 1),
  ('rt-arrest-booking', 'cat-police', 'Arrest & booking records', 'arrest-booking', 'Arrest and booking of an individual into custody.', 'Record an arrest and the booking of an individual into custody.', 'Arrestee identity, charges, arrest date, time, location, arresting officer, booking number, and mugshot.', 'Requested by media, attorneys, background checkers, or the public regarding a specific arrest.', '["arrest report","booking report","booking record","mugshot","jail booking"]', '["not an incident report","not a citation"]', '["arrest","booking","charges","mugshot","custody"]', '["arrestee name","arrest date","case or booking number","charges"]', '["document"]', 0, 'review_required', 0, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 20, '2026-06-05 19:04:12', '2026-06-05 19:04:12', 'electronic_search', 'electronic', 0, 1),
  ('rt-asset-inventory', 'cat-property', 'Fixed asset & equipment inventory', 'asset-inventory', 'List of city-owned fixed assets and equipment.', 'List city-owned fixed assets and equipment.', 'Asset description, identifier, location, value, and acquisition date.', 'Requested to review what equipment and assets the city owns.', '["asset inventory","fixed assets","equipment list","capital assets"]', '["not the vehicle fleet only","not surplus disposal"]', '["asset","inventory","equipment","fixed asset","capital"]', '["asset type","identifier","department","acquisition date"]', '["structured_data"]', 1, 'releasable', 1, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 20, '2026-06-05 20:18:28', '2026-06-05 20:18:28', 'electronic_search', 'electronic', 0, 1),
  ('rt-bfc5a656', 'cat-other', 'Animal impound & intake records', 'animal-impound', NULL, 'Document the intake, custody, care, and disposition of animals impounded or surrendered to the municipal animal shelter or animal control services.', 'Intake forms containing impound case number, intake date and time, animal species, breed, color, distinguishing marks, microchip number, location found or surrendered, finder or owner name and contact information, vaccination and medical status, rabies quarantine notes, bite incident history, hold period, and final disposition (adopted, reclaimed, transferred, euthanized). May include photos, veterinary notes, and release documentation.', 'Proof of animal ownership or reclaim; adoption records; investigation of animal cruelty or bite incidents; tracking lost pets; public health rabies exposure follow-up; statistical analysis of shelter intake and outcomes.', '["Animal shelter records","Animal control intake forms","Impound records","Animal custody records","Stray animal records","Animal surrender forms","Shelter intake logs"]', '["Maintained by Animal Services or Animal Control division","Covers individual animals, not business licenses for kennels or pet-related permits","Intake and disposition tracking, not just field enforcement citations"]', '["animal","impound","intake","shelter","stray","surrender","adoption","euthanize","microchip","rabies","quarantine","bite","disposition","reclaim"]', '["Impound or case number","Intake date","Species and breed","Finder or owner contact information","Disposition outcome"]', '["document","structured_data"]', 1, 'review_required', 0, NULL, 0, 0, NULL, 0, 'draft', 'discovered', 95, 900, '2026-06-05 22:19:35', '2026-06-05 22:19:35', 'electronic_search', 'electronic', 0, 1),
  ('rt-bids-rfps', 'cat-finance', 'Bids, RFPs & proposals', 'bids-rfps', 'Solicitations and the bids or proposals received in response.', 'Provide a solicitation and the bids or proposals submitted for it.', 'RFP or bid documents, submitted proposals, pricing, evaluations, and award decisions.', 'Requested by bidders, competitors, and the public reviewing a procurement.', '["bid","RFP","RFQ","proposal","solicitation","tender"]', '["not the executed contract","not invoices"]', '["bid","RFP","proposal","solicitation","award"]', '["solicitation number","project or subject","date"]', '["document"]', 0, 'review_required', 0, NULL, 0, 0, 'Submitted proposals may contain trade secrets; some are withheld until award.', 0, 'active', 'seed', NULL, 50, '2026-06-05 20:00:03', '2026-06-05 20:00:03', 'electronic_search', 'electronic', 0, 1),
  ('rt-boards-commissions', 'cat-governance', 'Boards & commissions records', 'boards-commissions', 'Records of city boards, commissions, and committees.', 'Provide agendas, minutes, and membership records for a board or commission.', 'Agendas, minutes, rosters, and appointment records for advisory and regulatory bodies.', 'Requested to follow the work of a specific board, commission, or committee.', '["board","commission","committee","advisory board","appointments"]', '["not the city council itself","not staff departments"]', '["board","commission","committee","appointment","roster"]', '["body name","meeting date","member name"]', '["document"]', 0, 'releasable', 1, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 60, '2026-06-05 20:00:03', '2026-06-05 20:00:03', 'electronic_search', 'electronic', 0, 1),
