  ('rt-building-permits', 'cat-permits', 'Building permits', 'building-permits', 'Permits authorizing construction, alteration, or demolition.', 'Authorize construction, alteration, or demolition of a structure.', 'Permit number, property address, scope of work, valuation, contractor, and inspections.', 'Requested by owners, buyers, contractors, and neighbors checking permitted work.', '["building permit","construction permit","permit record","remodel permit"]', '["not a code violation case","not a certificate of occupancy"]', '["permit","building","construction","valuation","contractor"]', '["property address","permit number","date","permit type"]', '["document"]', 0, 'releasable', 1, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 10, '2026-06-05 20:18:28', '2026-06-05 20:18:28', 'electronic_search', 'electronic', 0, 1),
