  ('rt-cad-logs', 'cat-police', 'Dispatch / call-for-service logs (CAD)', 'cad-logs', 'Computer-aided-dispatch metadata and response history for a call for service.', 'Record the dispatch metadata and response history for a call for service, from the computer-aided-dispatch system.', 'Call type, timestamps, units dispatched, response and clear times, disposition codes, and location; structured data, not audio.', 'Requested to see how a call was handled, response times, or call history at an address.', '["CAD log","dispatch log","call for service","CFS","incident history"]', '["not the 911 audio recording","not the incident report narrative"]', '["dispatch","CAD","call for service","disposition","response time"]', '["date and time","address","call or incident number","call type"]', '["structured_data"]', 1, 'review_required', 0, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 70, '2026-06-05 19:04:12', '2026-06-05 19:04:12', 'electronic_search', 'electronic', 0, 1),
