  ('rt-candidate-filings', 'cat-elections', 'Candidate filings & petitions', 'candidate-filings', 'Candidate applications, filings, and petitions for office.', 'Record candidate applications, filings, and petitions for office.', 'Applications for a place on the ballot, petitions, and eligibility filings.', 'Requested to verify who filed for office and their paperwork.', '["candidate filing","ballot application","petition","candidacy","nomination"]', '["not campaign finance","not election results"]', '["candidate","filing","petition","ballot","application"]', '["candidate","office","election date"]', '["document"]', 0, 'releasable', 1, NULL, 0, 0, NULL, 0, 'active', 'seed', NULL, 40, '2026-06-05 21:26:37', '2026-06-05 21:26:37', 'electronic_search', 'electronic', 0, 1),
