  ('repo-imptest', 'Test Import Drop', 'import', 'active', '{"path":"/opt/optimumq/imports/testdrop","mode":"push","subdir":"testdrop","end_to_end":true,"review_assignee":"fb3721fb-6d52-4437-837f-fc8a1be71887","template_id":"","record_type_id":""}', 60, '2026-07-07 04:07:43', ''),
  ('repo-laserfiche', 'Laserfiche ECM (Citywide Records)', 'laserfiche', 'active', '{"baseUrl":"http://localhost:4003","apiKey":"demo-laserfiche-key-replace-in-production"}', 5, '2026-06-09 21:22:05', 'The city''s central document management system. Most departments file their official records here.'),
  ('repo-paper-annex', 'City Hall Annex - Historical Vault', 'paper-index', 'active', '{"facility":"City Hall Annex"}', 61, '2026-06-09 13:27:14', 'Older recorded documents kept in the secured vault at the City Hall Annex: recorded deeds and property transfers, original plat maps and subdivision plans, and bound ordinance and resolution books. A search returns the vault location; staff retrieve the document on request.'),
  ('repo-paper-archive', 'City Records Center (Paper Archive)', 'paper-index', 'active', '{"facility":"City Records Center"}', 60, '2026-06-09 00:36:08', 'Physical paper records held in the City Records Center: older building permits, historical council minutes, archived case files and maps. A search here returns the box and shelf location of a record; staff retrieve it on request.'),
  ('repo-payroll-system', 'City Payroll System (sample)', 'structured', 'active', '{"path":"/opt/optimumq/sample_systems/payroll.json"}', 11, '2026-06-08 20:19:05', NULL),
