INSERT INTO "legal_sources" ("id", "jurisdiction_id", "name", "citation", "source_type", "description", "statute_text", "source", "created_at") VALUES
  ('11c8c74b-52ba-48ba-8b0a-138a0c1fc8a3', 'jur-tx', 'Examination Materials Exception', 'Tex. Gov''t Code § 552.114', 'statute', NULL, 'Information is excepted from disclosure if it is a test item, examination question, or answer, or information used to develop, administer, or evaluate an examination for employment, licensing, or academic purposes.', 'ai', '2026-06-09 23:40:22'),
  ('39745017-9133-42ef-9e44-e39a9f3d2c11', 'jur-tx', '911 Service Information', 'Tex. Health & Safety Code § 771.003', 'statute', NULL, 'Information about users of 911 service, including names, addresses, and telephone numbers, is confidential and may not be released except in specific circumstances.', 'ai', '2026-06-09 23:40:22'),
  ('450840ef-e567-486e-bca5-1038f80d7b40', 'jur-tx', 'Sensitive Personal Information', 'Tex. Gov''t Code § 552.134', 'statute', NULL, 'Information is excepted from disclosure if it relates to an individual''s immigration status or citizenship status, with certain law enforcement exceptions.', 'ai', '2026-06-09 23:40:22'),
  ('47def35a-fbc6-4698-926a-97e3bc15fa77', 'jur-tx', 'Home Address/Phone Exception', 'Tex. Gov''t Code § 552.024', 'statute', NULL, 'Information is excepted from disclosure if it is information that relates to the home address, home telephone number, or social security number of certain public officials and employees, or family members of certain persons.', 'ai', '2026-06-09 23:40:21'),
  ('599547b6-372e-40c9-a2e5-9766a83f2294', 'jur-tx', 'Expunged Records', 'Tex. Code Crim. Proc. Art. 55.03', 'statute', NULL, 'Information from expunged arrest records and files must be treated as if the arrest never occurred and may not be disclosed except in limited circumstances.', 'ai', '2026-06-09 23:40:22'),
  ('724b100d-5c87-43bd-be08-78f23118c334', 'jur-tx', 'Confidential Tax Information', 'Tex. Tax Code § 111.006', 'statute', NULL, 'Tax information is confidential and may not be disclosed except as specifically authorized, including taxpayer names connected with tax returns and specific tax information.', 'ai', '2026-06-09 23:40:22'),
  ('85551b57-f56b-4f6b-92d9-1518bdd58c29', 'jur-tx', 'Competitive Bidding Exception', 'Tex. Gov''t Code § 552.104', 'statute', NULL, 'Information is excepted from disclosure if it relates to competition or bidding and would give advantage to a competitor or bidder, including information submitted by a bidder or vendor in a competitive process before contract award.', 'ai', '2026-06-09 23:40:22'),
  ('98fcdb4f-769f-49e1-bb42-f92f7023cec8', 'jur-tx', 'Appraisal Information Exception', 'Tex. Gov''t Code § 552.131', 'statute', NULL, 'Information is excepted from disclosure if it relates to appraisal information for real or personal property and disclosure would provide advantage to a potential buyer or lessee, or interfere with assessment functions.', 'ai', '2026-06-09 23:40:22'),
  ('9e346711-0fd6-4919-a82f-d968bf079619', 'jur-tx', 'Emergency Telephone Number Exception', 'Tex. Gov''t Code § 552.125', 'statute', NULL, 'A telephone number, personal identification number, or other unique identifier issued to an individual user for access to automatic telephone services is excepted from disclosure.', 'ai', '2026-06-09 23:40:22'),
  ('adf32722-3bbe-40da-addb-89388741ffaf', 'jur-tx', 'Date of Birth Exception', 'Tex. Gov''t Code § 552.119', 'statute', NULL, 'A date of birth contained in a record of a governmental body is excepted from disclosure unless the disclosure is required or permitted under other law or regulation.', 'ai', '2026-06-09 23:40:22'),
  ('b917b0ef-06bc-46a7-a65d-e17a737bbe9b', 'jur-tx', 'Personal Information Exception', 'Tex. Gov''t Code § 552.117', 'statute', NULL, 'Information is excepted from disclosure if it is information that relates to the home address or telephone number of a peace officer or other designated official, or information that would reveal the home address or telephone number.', 'ai', '2026-06-09 23:40:22'),
  ('cada1fdb-04fc-4a71-8035-0974531ba4bb', 'jur-tx', 'Audit Working Papers', 'Tex. Gov''t Code § 552.139', 'statute', NULL, 'Working papers, records, or notes made during an audit or investigation are excepted from disclosure until the audit or investigation is completed.', 'ai', '2026-06-09 23:40:22'),
  ('cbe57afd-695b-4e19-b397-a594b94fc54b', 'jur-tx', 'Family Violence Victims', 'Tex. Code Crim. Proc. Art. 56.09', 'statute', NULL, 'Information related to the identity, residential address, telephone number, and place of employment of family violence victims is confidential and may not be disclosed.', 'ai', '2026-06-09 23:40:22'),
  ('d25999e4-9a5f-456a-98ec-31b892f281dc', 'jur-tx', 'Account and PIN Numbers', 'Tex. Gov''t Code § 552.136', 'statute', NULL, 'A bank account number, debit or charge card number, or other financial account number is excepted from disclosure, with certain exceptions for fraud investigations.', 'ai', '2026-06-09 23:40:22'),
  ('f7cde507-3086-4bd4-9af5-450ec17fe86d', 'jur-tx', 'Juvenile Records', 'Tex. Fam. Code § 58.003', 'statute', NULL, 'Juvenile records are confidential and may not be disclosed to the public except as specifically authorized by statute.', 'ai', '2026-06-09 23:40:22'),
  ('fa1fc590-7278-4983-a94e-46ba63ed4c74', 'jur-tx', 'Crime Victim Information', 'Tex. Gov''t Code § 552.1175', 'statute', NULL, 'Information is excepted from disclosure if it is information that identifies or tends to identify a person who is a victim of a crime.', 'ai', '2026-06-09 23:40:22'),
  ('ls-fed-ferpa', 'jur-tx', 'FERPA', '20 U.S.C. Sec. 1232g', 'statute', 'Family Educational Rights and Privacy Act (federal).', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-fed-hipaa', 'jur-tx', 'HIPAA Privacy Rule', '45 CFR Parts 160 and 164', 'regulation', 'Protected health information under the federal HIPAA Privacy Rule.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552026', 'jur-tx', 'Texas PIA - Student/education records', 'Tex. Gov''t Code Sec. 552.026', 'statute', 'Education records to the extent protected by FERPA.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552101', 'jur-tx', 'Texas PIA - Information confidential by law', 'Tex. Gov''t Code Sec. 552.101', 'statute', 'Information deemed confidential under other law.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552102', 'jur-tx', 'Texas PIA - Personnel file information', 'Tex. Gov''t Code Sec. 552.102', 'statute', 'Personnel-file information whose disclosure would be a clearly unwarranted invasion of privacy.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552107', 'jur-tx', 'Texas PIA - Attorney-client/litigation', 'Tex. Gov''t Code Sec. 552.107', 'statute', 'Information within the attorney-client privilege or related to pending litigation.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552108', 'jur-tx', 'Texas PIA - Law enforcement and prosecution', 'Tex. Gov''t Code Sec. 552.108', 'statute', 'Records of detection, investigation, or prosecution of crime where release would interfere.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552110', 'jur-tx', 'Texas PIA - Trade secrets', 'Tex. Gov''t Code Sec. 552.110', 'statute', 'Trade secrets and certain commercial or financial information of a private party.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552111', 'jur-tx', 'Texas PIA - Agency memoranda (deliberative)', 'Tex. Gov''t Code Sec. 552.111', 'statute', 'Interagency or intraagency memoranda reflecting advice, opinion, or recommendation in the deliberative process.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552117', 'jur-tx', 'Texas PIA - Personal info of officials/employees', 'Tex. Gov''t Code Sec. 552.117', 'statute', 'Home address, phone, SSN, and family info of officials/employees who elect confidentiality.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-5521175', 'jur-tx', 'Texas PIA - Peace officers and certain officials', 'Tex. Gov''t Code Sec. 552.1175', 'statute', 'Personal information of peace officers, judges, and other listed officials.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552130', 'jur-tx', 'Texas PIA - Motor vehicle records', 'Tex. Gov''t Code Sec. 552.130', 'statute', 'Driver''s license number, license plate, and motor vehicle record information.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552136', 'jur-tx', 'Texas PIA - Card and access device numbers', 'Tex. Gov''t Code Sec. 552.136', 'statute', 'Credit, debit, charge card, and access device numbers.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552137', 'jur-tx', 'Texas PIA - Email addresses of the public', 'Tex. Gov''t Code Sec. 552.137', 'statute', 'Email address of a member of the public communicating with a governmental body.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552139', 'jur-tx', 'Texas PIA - Security and critical infrastructure', 'Tex. Gov''t Code Sec. 552.139', 'statute', 'Government information related to security or critical infrastructure.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-552147', 'jur-tx', 'Texas PIA - Social Security numbers', 'Tex. Gov''t Code Sec. 552.147', 'statute', 'Confidentiality of a living person''s Social Security number.', NULL, 'seed', '2026-06-09 23:22:36'),
  ('ls-tx-mpa', 'jur-tx', 'Texas Medical Practice Act', 'Tex. Occ. Code Ch. 159', 'statute', 'Confidentiality of physician-patient communications and records.', NULL, 'seed', '2026-06-09 23:22:36')
