  ('jr-jur-ca-clarification', 'jur-ca', 'clarification', '{"enabled":false,"provenance":{"clarification_clock_effect":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65},"clarification_duty":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65},"vague_is_denial_ground":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65},"clarification_grace_days":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65},"abandonment_closure":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65},"closure_notice_required":{"source":"statute","citation":"Cal. Gov''t Code § 7922.535 (10-day determination + one 14-day extension); § 7922.500 bars using process to delay.","confidence":0.65}},"clarification_clock_effect":"runs_no_stop","clarification_duty":"none","vague_is_denial_ground":false,"clarification_grace_days":null,"abandonment_grace_days":null,"abandonment_closure":"unspecified","closure_notice_required":false,"second_notice_required":false,"second_notice_days":null}', 'survey-seed', '2026-07-14 01:44:35'),
