  ('ch-3d235df1', 'jur-tx', 'payment', '{"enabled":false,"provenance":{"deposit_clock_effect":{"source":"statute","citation":"Tex. Gov''t Code § 552.263(e) (deposit = re-receipt of the request); § 552.263(f) (10 business days, else withdrawn)","confidence":0.85},"deposit_grace_days":{"source":"statute","citation":"Tex. Gov''t Code § 552.263(f)","confidence":0.85},"deposit_lapse_action":{"source":"statute","citation":"Tex. Gov''t Code § 552.263(f); § 552.221(e)","confidence":0.8},"reissue_required_on_variance":{"source":"statute","citation":"Tex. Gov''t Code § 552.2615(c) (updated itemized statement required when actual charges exceed the estimate by more than 20%)","confidence":0.85},"reissue_blocks_collection":{"source":"statute","citation":"Tex. Gov''t Code § 552.2615(b) (no required itemized statement => may not collect more than $40)","confidence":0.85},"reissue_restarts_response_window":{"source":"statute","citation":"Tex. Gov''t Code § 552.2615(c) (fresh 10 business days to respond to the updated statement)","confidence":0.85}},"deposit_clock_effect":"toll_and_restart","deposit_grace_days":10,"deposit_lapse_action":"withdraw","reissue_required_on_variance":true,"reissue_blocks_collection":true,"reissue_restarts_response_window":true}', 'Seeded from the 2026-07-13 TX PIA review — DRAFT (enabled=false), pending city review + attestation.', '2026-07-14', '2026-07-14', 'legal-research-seed', '2026-07-14 01:29:53'),
  ('ch-4139a41c', 'jur-tx', 'clarification', '{"enabled":true,"provenance":{"clarification_clock_effect":{"source":"statute","citation":"does NOT toll or stop the five business-day response period","confidence":1},"clarification_duty":{"source":"statute","citation":"must extend opportunity to confer before deny as unduly burdensome","confidence":1},"vague_is_denial_ground":{"source":"statute","citation":"vagueness not mentioned as independent denial ground, only burden","confidence":0.9},"clarification_grace_days":{"source":"statute","citation":"within a reasonable time","confidence":0.8},"abandonment_closure":{"source":"statute","citation":"request may be treated as withdrawn","confidence":1},"closure_notice_required":{"source":"statute","citation":"denial must be in writing, but withdrawal treatment unspecified","confidence":0.7}},"clarification_clock_effect":"runs_no_stop","clarification_duty":"required_before_burden_denial","vague_is_denial_ground":false,"clarification_grace_days":null,"abandonment_grace_days":null,"abandonment_closure":"allowed","closure_notice_required":false}', 'Illinois 5 ILCS 140/3(g) establishes that when a request is unduly burdensome, the public body must offer the requester an opportunity to confer and narrow the request before denial. The clarification request does not toll or stop the five-business-day response clock, which continues to run. If the requester does not respond within a reasonable time, the request may be treated as withdrawn. A denial as unduly burdensome must be in writing with reasons specified.', '2026-07-09', '2026-07-13', 'auto-config', '2026-07-09 16:42:31'),
