INSERT INTO "redaction_rules" ("id", "jurisdiction_id", "title", "description", "category", "approval_status", "is_active", "source", "approved_by", "approved_at", "source_document", "effective_date", "expiration_date", "metadata", "sort_order", "created_at", "updated_at") VALUES
  ('2a3eb786-91a8-4aa3-a2aa-01754cfca61f', 'jur-tx', 'Home Addresses and Telephone Numbers', 'Redact home addresses, telephone numbers, and other contact information of individuals in public records, with specific exceptions for public officials. This protects residential privacy while maintaining government accountability.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:32:16', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:21', '2026-06-10 04:33:21'),
  ('47019ddd-d322-4175-b895-6eabe5eee7f0', 'jur-tx', 'Information Related to Competition or Bidding', 'Redact information related to pending bids, proposals, and contract negotiations until the procurement process is complete or contract is awarded to prevent unfair competitive advantage.', 'commercial', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:30:34', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:01'),
  ('50b5fade-b4ac-45e0-a6cc-5f536edc0236', 'jur-tx', 'Dates of Birth', 'Redact full dates of birth of individuals in public records, as this information can be used for identity theft. Consider releasing only month and year when context requires some age information.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:32:04', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:18'),
  ('61dddfe9-e5e0-4a5f-b22f-7e1535e907ad', 'jur-tx', 'Sealed or Expunged Criminal Records', 'Redact information related to arrests, criminal proceedings, or convictions that have been expunged or sealed by court order, or juvenile records not subject to public disclosure.', 'law_enforcement', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:31:13', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:12'),
  ('78adcc20-6734-4c91-bb2a-aa987a9c181e', 'jur-tx', 'Immigration Status Information', 'Redact information regarding an individual''s immigration status or citizenship status unless directly relevant to a lawful governmental purpose, to protect individual privacy rights.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:32:21', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:34'),
  ('7bcc33bb-d924-4da0-aef9-462394a9e648', 'jur-tx', 'Emergency Telephone Numbers (911 Information)', 'Redact recordings and information from emergency telephone calls and 911 communications, including names, addresses, and telephone numbers of callers, to protect caller privacy while balancing public safety interests.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:31:55', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:25'),
  ('bc856e9b-298f-411f-a604-fd8e36173146', 'jur-tx', 'Financial Account Numbers and Payment Information', 'Redact bank account numbers, routing numbers, credit card numbers (beyond last four digits), and other financial account information of individuals and entities to prevent fraud and identity theft.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:32:12', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:29'),
  ('c8355c25-7a5c-4fa8-8bd6-ad2ce3f78554', 'jur-tx', 'Audit Working Papers and Drafts', 'Redact preliminary audit reports, working papers, and draft audit findings until the final audit report is completed and issued to prevent misunderstanding and protect the deliberative audit process.', 'administrative', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:30:17', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:32:45'),
  ('dcdbd1d2-28b4-4833-9d1c-5457eacd1945', 'jur-tx', 'Information Related to Crime Victims and Witnesses', 'Redact names, addresses, and identifying information of crime victims, child abuse victims, sexual assault victims, family violence victims, and confidential witnesses to protect their safety and privacy.', 'law_enforcement', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:31:02', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:07'),
  ('f3eb3ab1-5ee0-41bc-914a-dc70cdbea47a', 'jur-tx', 'Tax Information and Appraisal Records', 'Redact confidential tax information, taxpayer identification numbers, and certain appraisal district information that would reveal confidential taxpayer data or proprietary valuation methods.', 'privacy', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:32:25', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:33:43'),
  ('f4658055-30cb-4ab9-9a5c-8e63e4c3b8ba', 'jur-tx', 'Real Estate Appraisal and Assessment Information', 'Redact real property appraisal information and methodology that, if disclosed before final appraisal, would give unfair advantage or undermine the governmental function of property assessment.', 'administrative', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:30:27', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:32:51'),
  ('f68eaddf-18a1-4f05-93dd-c5b02c17e731', 'jur-tx', 'Testing and Examination Materials', 'Redact test questions, answers, and examination materials used for licensing, employment, academic evaluation, or other governmental testing purposes to preserve test integrity and prevent unfair advantage.', 'administrative', 'approved', 1, 'ai', 'Kevin Hargrove', '2026-06-10 04:30:22', NULL, NULL, NULL, NULL, 0, '2026-06-09 23:40:22', '2026-06-10 04:32:55'),
  ('rr-attorney-client', 'jur-tx', 'Attorney-Client Privileged Communications', 'Withhold communications protected by the attorney-client privilege and information relating to pending litigation.', 'legal', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 100, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-cards', 'jur-tx', 'Card and Access Device Numbers', 'Redact credit, debit, and charge card numbers and other access device numbers.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 30, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-confidential-law', 'jur-tx', 'Information Confidential by Law', 'Withhold information made confidential by other applicable law.', 'administrative', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 140, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-deliberative', 'jur-tx', 'Deliberative Process / Pre-Decisional Documents', 'Withhold internal agency deliberations, drafts, and recommendations that are part of the decision-making process and not yet adopted as policy.', 'administrative', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 130, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-education', 'jur-tx', 'Student and Education Records', 'Redact personally identifiable information in education records protected under state law and FERPA.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 60, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-law-enforcement', 'jur-tx', 'Ongoing Law Enforcement and Prosecution', 'Withhold records whose release would interfere with the detection, investigation, or prosecution of crime.', 'law_enforcement', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 80, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-medical', 'jur-tx', 'Medical and Health Information', 'Redact protected health information, including diagnoses, treatment, and medical record numbers.', 'health', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 90, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-mvr', 'jur-tx', 'Motor Vehicle Record Information', 'Redact Texas driver''s license numbers, license plate numbers, and related motor vehicle record data.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 20, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-officials', 'jur-tx', 'Personal Information of Officials and Employees', 'Redact home address, personal phone, SSN, and family information of officials and employees who have elected confidentiality, and of peace officers and other protected officials.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 40, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-personnel', 'jur-tx', 'Personnel File Information', 'Withhold personnel-file information whose release would be a clearly unwarranted invasion of personal privacy.', 'personnel', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 70, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-public-email', 'jur-tx', 'Email Addresses of the Public', 'Redact the email address of a member of the public who communicated with the agency.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 50, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-security-infra', 'jur-tx', 'Security Infrastructure Details', 'Withhold information related to government security or critical infrastructure, such as network security assessments.', 'security', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 120, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-ssn', 'jur-tx', 'Social Security Numbers', 'Redact the Social Security number of any living person.', 'privacy', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 10, '2026-06-09 23:22:36', '2026-06-09 23:22:36'),
  ('rr-trade-secrets', 'jur-tx', 'Trade Secrets and Proprietary Business Information', 'Redact trade secrets and commercial or financial information of a private party where disclosure would cause competitive harm.', 'commercial', 'approved', 1, 'seed', NULL, NULL, NULL, NULL, NULL, NULL, 110, '2026-06-09 23:22:36', '2026-06-09 23:22:36')
