ee":null,"deposit":{"threshold":100,"percent":50},"estimateNotifyThreshold":40}}', 'system', '2026-07-15 00:24:22', '2026-07-15 00:24:22')
INSERT INTO "record_type_estimate_profiles" ("record_type_id", "quantities_json", "stats_json", "sample_size", "has_expert_seed", "source", "notes", "seeded_by", "seeded_at", "updated_at") VALUES
  ('rt-911-recordings', '{"searchHours":0.25,"reviewHours":1,"bwPages":0}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. One 911 audio call. No pages — the cost is REVIEW: audio redaction is done listening in real time.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-arrest-booking', '{"searchHours":0.25,"reviewHours":0.5,"bwPages":6}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. Arrest/booking packet. Review is the real cost: criminal-history and juvenile material must be screened.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-building-permits', '{"searchHours":1,"reviewHours":0.5,"bwPages":3,"oversizedPages":20}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. Kevin''s own worked example (FEE_ESTIMATE_KNOWLEDGE §7d): ~1 search hour, ~20 oversized blueprint pages, ~3 standard permit pages.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-cad-logs', '{"searchHours":0.25,"reviewHours":0.25,"bwPages":5}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. CAD/dispatch log for one call. Redaction is light but caller PII must be screened.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-citations', '{"searchHours":0.1,"reviewHours":0.1,"bwPages":2}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. A single citation. The cheapest thing a city produces; near-pure lookup.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-council-minutes', '{"searchHours":0.25,"reviewHours":0,"bwPages":12}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. Minutes for one meeting. ZERO review hours on purpose: this is already-public material, so there is nothing to redact.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-crash-reports', '{"searchHours":0.1,"reviewHours":0.1,"bwPages":3}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. TX CR-3 crash report: a standard form pulled by date/location. Little discretion, minimal redaction.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-incident-reports', '{"searchHours":0.25,"reviewHours":0.5,"bwPages":8}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. Typical single offense/incident report: a short records-system lookup, a redaction pass for victim/witness PII, ~8 pages.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-official-email', '{"searchHours":2,"reviewHours":6,"bwPages":150}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. THE LEAST RELIABLE SEED OF THE TEN, and deliberately so. Email volume is wildly request-dependent; §7 names it the type that wants a SCOPING SEARCH (hit count x avg pages), not a fixed seed. Treat this as a placeholder that a per-request override or the scoping search should displace.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57'),
  ('rt-police-video', '{"searchHours":0.5,"reviewHours":4,"bwPages":0}', '{}', 0, 1, 'human-expert', 'PROVISIONAL — seeded by assistant 2026-07-14, NOT confirmed by a records clerk. One body-worn-camera recording. Review dominates: video redaction runs slower than real time (faces, bystanders, minors). The single most expensive routine record a city holds.', 'Kevin Hargrove', '2026-07-14 20:50:57', '2026-07-14 20:50:57')
