INSERT INTO "workflow_rules" ("id", "name", "description", "enabled", "priority", "conditions", "actions", "source", "created_by", "created_at") VALUES
  ('wfr-confident', 'Confident match goes straight to the right team', 'If the record type is matched with high confidence and that record type has a known owning team, auto-complete intake and send it to that team for record search.', 1, 20, '[{"field":"record_type_confidence","op":"gte","value":70},{"field":"has_owner_team","op":"is_true"}]', '{"stage":"record_search","team":"matched","note":"Confident record-type match with a known owning team; intake auto-completed.","stop":true}', 'seed', NULL, '2026-06-22 20:20:41'),
  ('wfr-fallback', 'Fallback to Open Records intake', 'When no other rule applies, default to Open Records at intake so nothing is ever left unrouted.', 1, 100, '[]', '{"stage":"intake","team":"open_records","note":"No specific rule matched; default to Open Records intake.","stop":true}', 'seed', NULL, '2026-06-22 20:20:41'),
  ('wfr-sensitive', 'Sensitive matters stay with a person', 'If the request is flagged as a legal hold, an active investigation, or otherwise sensitive, keep it at intake for a human - even if the match looks confident.', 1, 5, '[{"field":"flags","op":"contains_any","value":["LEGAL_HOLD","ONGOING_INVESTIGATION","SENSITIVE"]}]', '{"stage":"intake","team":"open_records","note":"Held at intake for human review due to a sensitivity flag.","stop":true}', 'seed', NULL, '2026-06-22 20:20:41'),
  ('wfr-uncertain', 'Uncertain match to Open Records', 'If confidence in the record-type match is low, route to the Open Records team at intake for human triage.', 1, 30, '[{"field":"record_type_confidence","op":"lt","value":70}]', '{"stage":"intake","team":"open_records","note":"Low match confidence; routed to Open Records for human triage.","stop":true}', 'seed', NULL, '2026-06-22 20:20:41')
INSERT INTO "agent_rules" ("id", "rule_text", "enabled", "sort_order", "created_at", "created_by") VALUES
  ('rule-39ddd5e5', 'If a citizen mentions an officer name, vendor name, case number, or invoice number, use those terms verbatim in your search query — do not generalize.', 1, 20, '2026-06-02 05:22:57', 'system'),
  ('rule-52a43931', 'When citizens ask for actual records (incident reports, body camera footage, financial transactions, contracts), prioritize results from evidence and ERP systems over policy documents or contracts from the document library. The document library is best for policies, procedures, and reference material.', 1, 10, '2026-06-02 05:22:57', 'system')
INSERT INTO "layout_profiles" ("id", "name", "record_type_id", "description", "zones", "source", "status", "created_by", "created_at", "source_file_id", "source_filename", "layout_fingerprint", "safety_threshold", "processing_manager_name", "processing_manager_email", "updated_at", "kind", "field_map") VALUES
  ('tmpl-911-fields', '911 Caller PII (born-redacted)', 'rt-911-calls', NULL, '[]', 'manual', 'active', NULL, '2026-07-04 03:48:54', NULL, NULL, '{"kind":"fields","columns":["call_id","call_type","priority","received_at","caller_name","caller_phone","caller_address","incident_location","responding_units","disposition","narrative"]}', 60, NULL, NULL, NULL, 'fields', '[{"field":"caller_name","rule_id":null},{"field":"caller_phone","rule_id":null},{"field":"caller_address","rule_id":null}]')
